pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 amount, address caller) public {
        // Ensure caller is not zero address, amount > 0, and restrict amount to avoid overflow on caller's balance
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        // Give caller enough ether
        vm.deal(caller, amount);
        vm.prank(caller);
        try c.addToBalance{value: amount}() {
            // If addToBalance succeeded, try to withdraw from address(0)
        } catch {
            // If addToBalance reverted, withdraw from address(0) must also fail (since it has no balance)
            bool withdrawOk;
            try c.withdrawBalance() returns () {
                withdrawOk = true;
            } catch {
                withdrawOk = false;
            }
            assertTrue(!withdrawOk);
            return;
        }

        // After addToBalance succeeded, address(0) balance may be non-zero in mutant but zero in reference.
        // Address(0) cannot initiate transactions, but anyone can call withdrawBalance as address(0) using a low-level call from a helper.
        // Deploy a helper that calls withdrawBalance and observe if it reverts.
        Attacker helper = new Attacker(address(c));
        bool withdrawOk = helper.tryWithdraw();
        // In reference, address(0) balance is always 0, so withdraw must revert.
        // In mutant, address(0) could have received ether via addToBalance overflow, so withdraw could succeed.
        // The invariant is: a withdraw from address(0) must always revert.
        assertTrue(!withdrawOk);
    }
}

contract Attacker {
    C public c;
    constructor(address _c) {
        c = C(_c);
    }
    function tryWithdraw() external returns (bool) {
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        return success;
    }
}

