        // Measure initial contract balance
        uint256 balanceBefore = address(c).balance;

        // Fund the actor and call addToBalance
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // Measure final contract balance
        uint256 balanceAfter = address(c).balance;

        // Measure the user's balance via the public getter
        uint256 userBal = c.getBalance(actor);

        // The invariant: the sum of all user balances must equal the contract's balance.
        // Here we only test with one actor, so userBal == deltaBalance.
