contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Keep amount in a reasonable range to avoid overflow
        bound(amount, 1, 1000 ether);

        // Deploy the re-entrant attacker helper
        Attacker attacker = new Attacker(c);

        // Fund attacker
        vm.deal(address(attacker), amount);

        // Attacker deposits funds into C
        attacker.deposit{value: amount}();

        // Attacker initiates withdrawal, triggering reentrancy
        attacker.attack();

        // After withdrawal completes, the attacker's recorded balance in C must be 0
