        uint256 bal = c.getBalance(address(attacker));
        assertTrue(bal == 0);
    }
}

contract Attacker {
    C public target;
    uint256 public attackCount;

    constructor(C _target) {
        target = _target;
    }

    function deposit() external payable {
        target.addToBalance{value: msg.value}();
    }

    function attack() external {
        target.withdrawBalance();
    }

    receive() external payable {
        if (attackCount < 1) {
            attackCount++;
            // Re-enter withdrawBalance before the buggy version zeros the balance
            target.withdrawBalance();
        }
    }
}

