        try c.withdrawBalance() { success = true; } catch { success = false; }
        uint256 balAfter = c.getBalance(address(this));
        uint256 cBalAfter = address(c).balance;
        assert(balBefore >= cBalBefore - cBalAfter);
    }

    receive() external payable {}
}
